import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const [username, setUsername] = useState('');
  const [roomCode, setRoomCode] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isJoining, setIsJoining] = useState(false);
  const navigate = useNavigate();

  const createRoom = async () => {
    if (!username.trim()) {
      alert('Please enter your name to continue!');
      return;
    }

    setIsCreating(true);
    try {
      const response = await fetch('http://localhost:8080/api/rooms/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username }),
      });

      const data = await response.json();
      localStorage.setItem('userId', data.userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', data.role);
      
      navigate(`/room/${data.roomId}`);
    } catch (error) {
      console.error('Error creating room:', error);
      alert('Failed to create room.');
    } finally {
      setIsCreating(false);
    }
  };

  const joinRoom = async () => {
    if (!username.trim()) {
      alert('Please enter your name first!');
      return;
    }
    if (!roomCode.trim()) {
      alert('Please enter a room code to join!');
      return;
    }

    setIsJoining(true);
    try {
      const response = await fetch('http://localhost:8080/api/rooms/join', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ roomId: roomCode, username }),
      });

      if (!response.ok) {
        throw new Error('Room not found');
      }

      const data = await response.json();
      localStorage.setItem('userId', data.userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', data.role);
      
      navigate(`/room/${roomCode}`);
    } catch (error) {
      console.error('Error joining room:', error);
      alert('Room not found. Please check the room code and try again!');
    } finally {
      setIsJoining(false);
    }
  };

  return (
    <div className="home-container">
      <div className="home-card fade-in-up">
        <h1>YouTube Watch Party</h1>
        <p>Watch YouTube videos together with friends in real-time!<br /></p>
        
        <div className="input-group">
          <input
            type="text"
            placeholder="Enter your GoodName name"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && createRoom()}
          />
        </div>

        <div className="action-buttons">
          <button 
            className="btn btn-primary"
            onClick={createRoom}
            disabled={isCreating}
          >
            {isCreating ? (
              <>
                <span className="loading"></span> Creating...
              </>
            ) : (
              '✨ Create New Room'
            )}
          </button>
          
          <div className="divider">OR</div>
          
          <div className="join-section">
            <input
              type="text"
              placeholder="Enter room code"
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
              onKeyPress={(e) => e.key === 'Enter' && joinRoom()}
            />
            <button 
              className="btn btn-primary"
              onClick={joinRoom}
              disabled={isJoining}
            >
              {isJoining ? (
                <>
                  <span className="loading"></span> Joining...
                </>
              ) : (
                'Join Room'
              )}
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Home;
